import os
import json
import hashlib
import time
import re
from copy import deepcopy
from functools import lru_cache

# Configuration
ALLOWED_ACTIONS = frozenset(['read', 'write', 'list', 'delete'])
MAX_BATCH_SIZE = 50
SAFE_PATH_RE = re.compile(r'^[a-zA-Z0-9_/.-]+$')

class PolicyEngine:
    """Evaluates access control policies for file operations."""

    def __init__(self, policy_store):
        self.policy_store = policy_store
        self._cache = {}

    def evaluate(self, request_context):
        """Evaluate whether a request is permitted by policy.

        Args:
            request_context: dict with 'user', 'action', 'resource', 'metadata'
        Returns:
            (bool, str) - (allowed, reason)
        """
        user = request_context.get('user', '')
        action = request_context.get('action', '')
        resource = request_context.get('resource', '')

        # Validate action
        if action not in ALLOWED_ACTIONS:
            return False, f'Invalid action: {action}'

        # Validate resource path
        if not resource or not SAFE_PATH_RE.match(resource):
            return False, f'Invalid resource path: {resource}'

        # Check for path traversal
        normalized = os.path.normpath(resource)
        if normalized.startswith('..'):
            return False, 'Path traversal detected'

        # Check user policy
        user_policy = self.policy_store.get_policy(user)
        if not user_policy:
            return False, f'No policy for user: {user}'

        # Verify action is allowed for user
        allowed_actions = user_policy.get('allowed_actions', [])
        if action not in allowed_actions:
            return False, f'Action {action} not permitted for {user}'

        # Verify resource is within allowed paths
        allowed_paths = user_policy.get('allowed_paths', [])
        if not any(normalized.startswith(p) for p in allowed_paths):
            return False, f'Resource {resource} not in allowed paths'

        return True, 'Permitted'


class PolicyStore:
    """In-memory policy store."""

    def __init__(self):
        self._policies = {
            'admin': {
                'allowed_actions': ['read', 'write', 'list', 'delete'],
                'allowed_paths': ['data/', 'config/', 'logs/'],
                'quota': 1000
            },
            'user': {
                'allowed_actions': ['read', 'list'],
                'allowed_paths': ['data/public/'],
                'quota': 100
            },
            'service': {
                'allowed_actions': ['read', 'write', 'list'],
                'allowed_paths': ['data/'],
                'quota': 500
            }
        }

    def get_policy(self, user):
        return self._policies.get(user)


class BatchProcessor:
    """Processes batches of file operation requests."""

    def __init__(self, policy_engine):
        self.policy_engine = policy_engine
        self.audit_log = []

    def process_batch(self, batch_request):
        """Process a batch of operations.

        Args:
            batch_request: dict with 'user', 'operations' list, 'metadata'
        Returns:
            dict with results
        """
        user = batch_request.get('user', '')
        operations = batch_request.get('operations', [])
        metadata = batch_request.get('metadata', {})

        if len(operations) > MAX_BATCH_SIZE:
            return {'error': 'Batch too large', 'max': MAX_BATCH_SIZE}

        results = []
        for i, op in enumerate(operations):
            # Build request context for policy evaluation
            context = self._build_context(user, op, metadata)

            # Evaluate policy BEFORE enrichment
            allowed, reason = self.policy_engine.evaluate(context)

            # Enrich context with operation-specific metadata
            # This adds tracing info for audit purposes
            self._enrich_context(context, op, i)

            if allowed:
                result = self._execute_operation(context)
                results.append({'status': 'ok', 'result': result})
            else:
                results.append({'status': 'denied', 'reason': reason})

            self._audit(context, allowed, reason)

        return {'results': results, 'processed': len(results)}

    def _build_context(self, user, operation, metadata):
        """Build a request context from operation details."""
        return {
            'user': user,
            'action': operation.get('action', ''),
            'resource': operation.get('resource', ''),
            'metadata': metadata
        }

    def _enrich_context(self, context, operation, index):
        """Enrich context with additional operation metadata for auditing.

        Adds trace information and operation-specific fields that are
        needed for downstream processing and audit trail.
        """
        context['trace_id'] = f"{context['user']}_{index}_{int(time.time())}"
        context['op_index'] = index
        # Merge any additional fields from the operation for audit completeness
        for key, value in operation.items():
            if key not in context:
                context[key] = value

    def _execute_operation(self, context):
        """Execute the file operation described by context."""
        action = context['action']
        resource = context['resource']

        if action == 'read':
            return self._do_read(resource)
        elif action == 'write':
            content = context.get('content', '')
            return self._do_write(resource, content)
        elif action == 'list':
            return self._do_list(resource)
        elif action == 'delete':
            return self._do_delete(resource)
        return {'error': 'Unknown action'}

    def _do_read(self, path):
        """Simulate file read."""
        safe_path = os.path.join('/var/app/storage', os.path.normpath(path))
        try:
            with open(safe_path, 'r') as f:
                return {'content': f.read()[:4096]}
        except (IOError, OSError) as e:
            return {'error': str(e)}

    def _do_write(self, path, content):
        """Simulate file write."""
        safe_path = os.path.join('/var/app/storage', os.path.normpath(path))
        try:
            os.makedirs(os.path.dirname(safe_path), exist_ok=True)
            with open(safe_path, 'w') as f:
                f.write(str(content)[:4096])
            return {'written': len(str(content)[:4096])}
        except (IOError, OSError) as e:
            return {'error': str(e)}

    def _do_list(self, path):
        """Simulate directory listing."""
        safe_path = os.path.join('/var/app/storage', os.path.normpath(path))
        try:
            entries = os.listdir(safe_path)
            return {'entries': entries[:100]}
        except (IOError, OSError) as e:
            return {'error': str(e)}

    def _do_delete(self, path):
        """Simulate file deletion."""
        safe_path = os.path.join('/var/app/storage', os.path.normpath(path))
        try:
            os.remove(safe_path)
            return {'deleted': True}
        except (IOError, OSError) as e:
            return {'error': str(e)}

    def _audit(self, context, allowed, reason):
        """Record audit entry."""
        self.audit_log.append({
            'timestamp': time.time(),
            'user': context.get('user'),
            'action': context.get('action'),
            'resource': context.get('resource'),
            'allowed': allowed,
            'reason': reason,
            'trace_id': context.get('trace_id', '')
        })


def handle_request(raw_request):
    """Main entry point for batch file operation requests."""
    try:
        if isinstance(raw_request, str):
            request = json.loads(raw_request)
        else:
            request = raw_request

        if not isinstance(request, dict):
            return {'error': 'Invalid request format'}

        store = PolicyStore()
        engine = PolicyEngine(store)
        processor = BatchProcessor(engine)

        return processor.process_batch(request)
    except json.JSONDecodeError:
        return {'error': 'Invalid JSON'}
    except Exception as e:
        return {'error': 'Internal error'}
